function UICultivateEquipComparedView:__init()
    self.__EventOperateEquipOrCore = nil
end

function UICultivateEquipComparedView:__delete()
    self.__EventOperateEquipOrCore = nil
end

function UICultivateEquipComparedView:Awake()
    --UIEventProxy.Create(self.IntroductionNodes.gameObject).onPointerClick = Bind(self, self.OnClickLeerierBereniceAction)

    self.__EventOperateEquipOrCore = Events.AddListener(Constants.EventNames.UICultivateEquipOperateEquipOrCore, Bind(self, self.OnEventOperateEquipOrCore))

end

function UICultivateEquipComparedView:Start()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function UICultivateEquipComparedView:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) and not GuideUtils.IsInGuiding() then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local camera = UIModule.RootCanvas.canvas.worldCamera
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.CurEquipIntroductionNode, position, camera)
            local isActive = KTool.IsActive(self.CompareIntroductionNode.gameObject)
            local isInRect1 = isActive and RectTransformUtility.RectangleContainsScreenPoint(self.CompareIntroductionNode, position, camera)
            if not (isInRect or isInRect1) then
                --Events.Broadcast(Constants.EventNames.UICultivateEquipCompareViewClose)
                self:HideView()
            end
        end
    end
end

function UICultivateEquipComparedView:OnDestroy()
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
    Events.RemoveListener(Constants.EventNames.UICultivateEquipOperateEquipOrCore, self.__EventOperateEquipOrCore)
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

