function UICultivateEquipComparedView:RefreshUI(equipIdList, curDojo, compareDojo, equipType, part, playerCardId)

    local equipDojoList = {}
    for i = 1, Constants.CardEquipmentNo do
        local id = checkNumber(equipIdList[i])
        if id > 0 then
            equipDojoList[i] = equipComp:GetEquipById(id)
        end
    end

    self:RefreshUIByEquipDojoList(equipDojoList, curDojo, compareDojo, equipType, part, playerCardId)
end

function UICultivateEquipComparedView:RefreshUIByEquipDojoList(equipDojoList, curDojo, compareDojo, equipType, part, playerCardId)
    local curParams, compareParams = self:InitParams(equipDojoList, curDojo, compareDojo, equipType, part)
    KTool.SetActive(self.Container.gameObject, true)
    KTool.SetActive(self.Shadow.gameObject, compareParams ~= nil)
    KTool.SetActive(self.CompareIntroductionNode.gameObject, compareParams ~= nil)
    self:RefreshEquipIntroductionNode(self.CurEquipIntroductionNode, curParams, equipType, playerCardId)
    if compareParams ~= nil then
        self:RefreshEquipIntroductionNode(self.CompareIntroductionNode, compareParams, equipType, playerCardId)
    end
end

function UICultivateEquipComparedView:InitParams(equipDojoList, curDojo, compareDojo, equipType, part)
    local isExistsCompareDojo = compareDojo ~= nil
    local isCompare = curDojo ~= nil and isExistsCompareDojo
    local isCore = equipType == EquipType.Core
    local curParams, compareParams
    if isCompare then
        curParams = {
            part = part,
            dojo = curDojo,
            status = Status.Installed,
            equipDojoList = isCore and equipDojoList or nil,
        }

        local compareStatus
        if checkNumber(compareDojo.playerCardId) == 0 then
            compareStatus = isCore and Status.Replace or Status.CultivateAndReplace
        else
            compareStatus = Status.Installed
        end

        compareParams = {
            part = part,
            dojo = compareDojo,
            equipDojoList = isCore and equipDojoList or nil,
            status =  isCore and Status.Replace or Status.CultivateAndReplace,
            iShowCanActive = true,
        }

    elseif isExistsCompareDojo then
        curParams = {
            part = part,
            dojo = compareDojo,
            equipDojoList = isCore and equipDojoList or nil,
            status = isCore and Status.Install or Status.CultivateAndInstall,
            iShowCanActive = true,
        }
    else
        curParams = {
            part = part,
            dojo = curDojo,
            status = isCore and Status.Uninstall or Status.CultivateAndUninstall,
            equipDojoList = isCore and equipDojoList or nil,

        }
    end
    return curParams, compareParams
end


function UICultivateEquipComparedView:RefreshEquipCultivateUI(curDojo, compareDojo, equipType, part)
    local curParams, compareParams = self:InitEquipCultivateParams(curDojo, compareDojo, part)
    KTool.SetActive(self.Container.gameObject, true)
    KTool.SetActive(self.Shadow.gameObject, compareParams ~= nil)
    KTool.SetActive(self.CompareIntroductionNode.gameObject, compareParams ~= nil)
    self:RefreshEquipIntroductionNode(self.CurEquipIntroductionNode, curParams, equipType, nil, true)
    if compareParams ~= nil then
        self:RefreshEquipIntroductionNode(self.CompareIntroductionNode,  compareParams, equipType, nil, true)
    end
end

function UICultivateEquipComparedView:InitEquipCultivateParams(curDojo, compareDojo, part)
    local isExistsCompareDojo = compareDojo ~= nil
    local curParams, compareParams
    curParams = {
        part = part,
        dojo = curDojo,
        status = Status.HideButton,
    }
    if isExistsCompareDojo then
        compareParams = {
            part = part,
            dojo = compareDojo,
            status = Status.HideButton,
        }
    end
    return curParams, compareParams
end


function UICultivateEquipComparedView:RefreshEquipIntroductionNode(node, params, equipType, playerCardId, isHideLockBtn)
    ---@type UICultivateEquipIntroductionNodeMB
    local env = CfUtils.GetLuaScr(node.gameObject, IntroductionNodeMBPath)
    if isNull(env) then return end
    env:RefreshUI(params, equipType, playerCardId, isHideLockBtn)

end

function UICultivateEquipComparedView:HideView()
    if self.closeCb then
        self.closeCb()
    end
    GameUtils.UpdateUIShowState(self.controller.gameObject, false)
end

